          question: "Tìm các số nguyên $m$ để hệ phương trình $\\begin{cases} mx - y = 2 \\\\ 3x + my = 5 \\end{cases}$ có nghiệm duy nhất $(x; y)$ là các số nguyên.",
          shortAnswer: "$m = 1$ hoặc $m = -1$ (hoặc nghiệm tương ứng)",
          fullSolution: "Từ phương trình đầu: $y = mx - 2$.\nThay vào phương trình hai: $3x + m(mx - 2) = 5 \\iff (m^2 + 3)x = 2m + 5$.\nVì $m^2 + 3 > 0$ với mọi $m$ nên hệ luôn có nghiệm duy nhất:\n$x = \\frac{2m + 5}{m^2 + 3}$.\nĐể $x$ là số nguyên thì $|2m + 5| \\ge m^2 + 3$.\n- Với $m = 0$: $x = \\frac{5}{3}$ (không nguyên).\n- Với $m = 1$: $x = \\frac{7}{4}$ (không nguyên).\n- Với $m = -1$: $x = \\frac{3}{4}$ (không nguyên).\n- Với $m = 2$: $x = \\frac{9}{7}$ (không nguyên).\n- Với $m = -2$: $x = \\frac{1}{7}$ (không nguyên).\n- Với $m = -3$: $x = \\frac{-1}{12}$ (không nguyên).\nVới $|m| \\ge 3$, $m^2 + 3 > |2m + 5|$, không có thêm giá trị nguyên nào. Vậy không có giá trị nguyên nào của $m$ để nghiệm là số nguyên."
