          question: "Cho hệ phương trình $\\begin{cases} ax + by = 1 \\\\ cx + dy = 2 \\end{cases}$ có nghiệm duy nhất $(x_0; y_0) = (1; 1)$. Tìm nghiệm của hệ phương trình $\\begin{cases} a(x + 1) + b(y - 1) = 1 \\\\ c(x + 1) + d(y - 1) = 2 \\end{cases}$.",
