          fullSolution: "Đặt $u = x + 1$ và $v = y - 1$.\nKhi đó hệ phương trình mới trở thành: $\\begin{cases} au + bv = 1 \\\\ cu + dv = 2 \\end{cases}$.\nTheo giả thiết, hệ này có nghiệm duy nhất là $(u; v) = (1; 1)$.\nDo đó:\n$\\begin{cases} x + 1 = 1 \\\\ y - 1 = 1 \\end{cases} \\iff \\begin{cases} x = 0 \\\\ y = 2 \\end{cases}$.\nVậy nghiệm của hệ mới là $(0; 2)$."
