      description: "Với các hệ phương trình chứa phân thức $\\frac{1}{x}, \\frac{1}{y}$, căn thức $\\sqrt{x-a}, \\sqrt{y-b}$ hoặc các biểu thức lặp lại, ta đặt ẩn phụ $u, v$ thích hợp kèm điều kiện xác định. Sau khi giải hệ bậc nhất đối với $u, v$, ta thay ngược lại tìm nghiệm $x, y$ ban đầu.",
