          shortAnswer: "$u \\ge 0$ và $v \\ge 0$",
          fullSolution: "Vì $u$ và $v$ là giá trị của căn bậc hai số học nên điều kiện bắt buộc của các ẩn phụ là $u \\ge 0$ và $v \\ge 0$ (với $x \\ge 1, y \\ge -3$)."
