      description: "Các công thức cơ bản của chuyển động đều: $s = v \\cdot t, v = \\frac{s}{t}, t = \\frac{s}{v}$.\n- Chuyển động đường thủy: $v_{\\text{xuôi}} = v_{\\text{thực}} + v_{\\text{dòng}}$, $v_{\\text{ngược}} = v_{\\text{thực}} - v_{\\text{dòng}}$.\n- Hai xe chuyển động ngược chiều gặp nhau: $s_1 + s_2 = s_{\\text{tổng}}$. Hai xe chuyển động cùng chiều đuổi kịp nhau: $s_1 - s_2 = s_{\\text{ban đầu}}$.",
