          shortAnswer: "Xe 1: $45\\text{ km/h}$, Xe 2: $35\\text{ km/h}$",
          fullSolution: "Gọi vận tốc xe 1 là $x$ (km/h) và xe 2 là $y$ (km/h) ($x > y > 0$).\n- Hiệu vận tốc: $x - y = 10$.\n- Tổng quãng đường hai xe đi được trong $1{,}5$ giờ là: $1{,}5x + 1{,}5y = 120 \\iff x + y = 80$.\nTa có hệ phương trình: $\\begin{cases} x - y = 10 \\\\ x + y = 80 \\end{cases} \\iff \\begin{cases} 2x = 90 \\\\ y = 80 - x \\end{cases} \\iff \\begin{cases} x = 45 \\\\ y = 35 \\end{cases}$.\nVậy vận tốc xe thứ nhất là $45\\text{ km/h}$ và xe thứ hai là $35\\text{ km/h}$."
