          question: "Một ô tô đi từ $A$ đến $B$ với một vận tốc và thời gian dự định. Nếu xe chạy với vận tốc nhanh hơn $10\\text{ km/h}$ thì đến nơi sớm hơn dự định $2$ giờ. Nếu xe chạy chậm hơn $10\\text{ km/h}$ thì đến nơi muộn hơn dự định $3$ giờ. Tính quãng đường $AB$.",
          shortAnswer: "$600\\text{ km}$",
          fullSolution: "Gọi vận tốc dự định là $v$ (km/h) và thời gian dự định là $t$ (giờ) ($v > 10, t > 2$). Quãng đường $AB = v \\cdot t$.\n- Tăng vận tốc $10\\text{ km/h}$: $(v + 10)(t - 2) = vt \\iff vt - 2v + 10t - 20 = vt \\iff -2v + 10t = 20 \\iff -v + 5t = 10$ (1).\n- Giảm vận tốc $10\\text{ km/h}$: $(v - 10)(t + 3) = vt \\iff vt + 3v - 10t - 30 = vt \\iff 3v - 10t = 30$ (2).\nTừ (1) suy ra: $v = 5t - 10$. Thế vào (2):\n$3(5t - 10) - 10t = 30 \\iff 15t - 30 - 10t = 30 \\iff 5t = 60 \\iff t = 12$ giờ.\nSuy ra $v = 5(12) - 10 = 50\\text{ km/h}$.\nQuãng đường $AB$ là: $S = v \\cdot t = 50 \\times 12 = 600\\text{ km}$."
