          shortAnswer: "Xuôi dòng: $27\\text{ km/h}$, ngược dòng: $21\\text{ km/h}$",
          fullSolution: "Gọi thời gian xuôi dòng $1\\text{ km}$ là $u$ (giờ) và ngược dòng $1\\text{ km}$ là $v$ (giờ) ($u, v > 0$). Khi đó $v_x = \\frac{1}{u}, v_n = \\frac{1}{v}$.\nTheo đề bài ta có hệ phương trình:\n$\\begin{cases} 108u + 63v = 7 \\\\ 81u + 84v = 7 \\end{cases}$.\nNhân PT 1 với 3 và PT 2 với 4:\n$\\begin{cases} 324u + 189v = 21 \\\\ 324u + 336v = 28 \\end{cases}$.\nTrừ hai phương trình: $147v = 7 \\iff v = \\frac{7}{147} = \\frac{1}{21}$.\nThay vào: $108u + 63\\left(\\frac{1}{21}\\right) = 7 \\iff 108u + 3 = 7 \\iff 108u = 4 \\iff u = \\frac{4}{108} = \\frac{1}{27}$.\nSuy ra vận tốc xuôi dòng là $v_x = \\frac{1}{u} = 27\\text{ km/h}$ và ngược dòng là $v_n = \\frac{1}{v} = 21\\text{ km/h}$."
