          shortAnswer: "Đội 1: $30$ ngày, đội 2: $30$ ngày",
          fullSolution: "Gọi thời gian làm một mình của đội 1 là $x$ (ngày) và đội 2 là $y$ (ngày) ($x, y > 15$).\nNăng suất ban đầu: $1$ ngày đội 1 làm $\\frac{1}{x}$, đội 2 làm $\\frac{1}{y}$.\nLàm chung trong $15$ ngày xong việc $\\implies \\frac{1}{x} + \\frac{1}{y} = \\frac{1}{15}$.\n- Trong $6$ ngày làm chung, hai đội làm được: $6 \\times \\frac{1}{15} = \\frac{2}{5}$ công việc.\n- Phần công việc còn lại là: $1 - \\frac{2}{5} = \\frac{3}{5}$ công việc.\nĐội 2 làm với năng suất gấp đôi là $2 \\times \\frac{1}{y} = \\frac{2}{y}$ trong $9$ ngày thì xong phần còn lại:\n$9 \\times \\frac{2}{y} = \\frac{3}{5} \\iff \\frac{18}{y} = \\frac{3}{5} \\iff 3y = 90 \\iff y = 30$ ngày.\nThay $y = 30$ vào phương trình ban đầu:\n$\\frac{1}{x} + \\frac{1}{30} = \\frac{1}{15} \\iff \\frac{1}{x} = \\frac{2}{30} - \\frac{1}{30} = \\frac{1}{30} \\iff x = 30$ ngày.\nVậy mỗi đội làm một mình với năng suất ban đầu đều mất $30$ ngày."
