          shortAnswer: "Xét hiệu: $\\frac{a}{b} + \\frac{b}{a} - 2 = \\frac{(a - b)^2}{ab} \\ge 0$.",
          fullSolution: "Xét hiệu của hai vế:\n$$H = \\frac{a}{b} + \\frac{b}{a} - 2 = \\frac{a^2 + b^2 - 2ab}{ab} = \\frac{(a - b)^2}{ab}$$\nVì $(a - b)^2 \\ge 0$ với mọi $a, b$ và $a, b$ cùng dấu nên $ab > 0$.\nDo đó: $H = \\frac{(a - b)^2}{ab} \\ge 0 \\implies \\frac{a}{b} + \\frac{b}{a} \\ge 2$.\nDấu \"=\" xảy ra khi và chỉ khi $a - b = 0 \\iff a = b$."
