          fullSolution: "Khai triển các dấu ngoặc và thu gọn hai vế:\n$$2x - 6 + 5 < 4x + 4 - 3$$\n$$2x - 1 < 4x + 1$$\nChuyển các hạng tử chứa $x$ sang vế trái, các hằng số sang vế phải:\n$$2x - 4x < 1 + 1$$\n$$-2x < 2$$\nChia cả hai vế cho $-2 < 0$, đổi chiều bất phương trình:\n$$x > \\frac{2}{-2} \\iff x > -1$$\nVậy nghiệm của bất phương trình là $x > -1$."
