          question: "Giải bất phương trình: $\\frac{3x - 1}{4} - \\frac{x + 2}{3} \\ge 1$.",
          shortAnswer: "$x \\ge \\frac{23}{5}$",
          fullSolution: "Quy đồng mẫu số chung là $12 > 0$ và khử mẫu:\n$$3(3x - 1) - 4(x + 2) \\ge 12$$\n$$9x - 3 - 4x - 8 \\ge 12$$\n$$5x - 11 \\ge 12$$\n$$5x \\ge 12 + 11$$\n$$5x \\ge 23 \\iff x \\ge \\frac{23}{5}$$\nVậy nghiệm của bất phương trình là $x \\ge \\frac{23}{5}$."
