          shortAnswer: "$x > 3$",
          fullSolution: "Quy đồng với mẫu số chung là $10 > 0$ rồi khử mẫu:\n$$2(2x + 1) - 5(x - 3) < 20 - x$$\n$$4x + 2 - 5x + 15 < 20 - x$$\n$$-x + 17 < 20 - x$$\n$$-x + x < 20 - 17$$\n$$0x < 3$$\nBất đẳng thức $0x < 3 \\iff 0 < 3$ luôn đúng với mọi số thực $x$.\nVậy bất phương trình nghiệm đúng với mọi $x \\in \\mathbb{R}$."
