          question: "Tìm tất cả các số nguyên âm $x$ thỏa mãn bất phương trình: $\\frac{2x - 3}{3} > \\frac{5x + 1}{6} - 1$.",
          shortAnswer: "$x \\in \\{-6; -5; -4; -3; -2; -1\\}$",
          fullSolution: "Quy đồng mẫu số chung là $6 > 0$:\n$$2(2x - 3) > (5x + 1) - 6$$\n$$4x - 6 > 5x - 5$$\n$$4x - 5x > -5 + 6$$\n$$-x > 1 \\iff x < -1$$\nVì $x$ là số nguyên âm thỏa mãn điều kiện $x < -1$ nên:\n$$x \\in \\{\\dots; -4; -3; -2\\}$$\nVậy tập các số nguyên âm thỏa mãn là các số nguyên $x \\le -2$."
