          shortAnswer: "Từ $151\\text{ phút}$ trở lên.",
          fullSolution: "- Gọi $x$ là số phút gọi trong tháng ($x \\in \\mathbb{N}^*$).\n- Số tiền trả theo gói A là: $60\\,000 + 800x$ (đồng).\n- Số tiền trả theo gói B là: $1\\,200x$ (đồng).\nĐể gói A tiết kiệm hơn gói B thì chi phí gói A phải nhỏ hơn gói B:\n$$60\\,000 + 800x < 1\\,200x$$\n$$1\\,200x - 800x > 60\\,000$$\n$$400x > 60\\,000 \\iff x > \\frac{60\\,000}{400} = 150$$\nVì $x$ là số phút nguyên dương nên $x \\ge 151$.\nVậy người đó cần gọi từ $151$ phút trở lên trong tháng thì dùng gói A sẽ tiết kiệm hơn gói B."
