          shortAnswer: "Tối thiểu $376$ ly trà sữa.",
          fullSolution: "- Gọi $x$ là số ly trà sữa bán được trong một tháng ($x \\in \\mathbb{N}^*$).\n- Tổng doanh thu thu về: $28\\,000x$ (đồng).\n- Tổng chi phí bỏ ra: $6\\,000\\,000 + 12\\,000x$ (đồng).\nĐể quán có lãi thì doanh thu phải lớn hơn chi phí:\n$$28\\,000x > 6\\,000\\,000 + 12\\,000x$$\n$$16\\,000x > 6\\,000\\,000 \\iff x > \\frac{6\\,000\\,000}{16\\,000} = 375$$\nVì $x$ là số nguyên nên $x \\ge 376$.\nVậy quán cần bán tối thiểu $376$ ly trà sữa mỗi tháng để bắt đầu có lợi nhuận."
