          question: "Bạn Bình thuê một chiếc xe đạp công cộng để tập thể dục buổi sáng. Giá cước của xe đạp: $30\\text{ phút đầu}$ được tính trọn gói $5\\,000\\text{ đồng}$, từ phút thứ $31$ trở đi tính thêm $1\\,000\\text{ đồng}$ cho mỗi phút. Trong tài khoản bạn Bình có đúng $35\\,000\\text{ đồng}$. Hỏi bạn Bình có thể thuê xe tối đa bao nhiêu phút?",
          shortAnswer: "Tối đa $60\\text{ phút}$.",
          fullSolution: "- Gọi tổng thời gian thuê xe là $t$ phút ($t > 30$, $t \\in \\mathbb{N}^*$).\n- Thời gian vượt quá 30 phút đầu là: $t - 30$ (phút).\n- Tổng số tiền thuê xe là: $5\\,000 + 1\\,000(t - 30)$ (đồng).\nSố tiền này không vượt quá số dư trong tài khoản ($35\\,000$ đồng):\n$$5\\,000 + 1\\,000(t - 30) \\le 35\\,000$$\n$$1\\,000(t - 30) \\le 30\\,000$$\n$$t - 30 \\le 30 \\iff t \\le 60$$\nVậy bạn Bình có thể thuê xe đạp tối đa trong $60$ phút."
