          fullSolution: "- Gọi điểm trung bình học kỳ 2 của bạn Mai là $y$ ($0 \\le y \\le 10$).\n- Điểm trung bình cả năm được tính theo công thức:\n$$\\text{ĐTB}_{\\text{cả năm}} = \\frac{\\text{ĐTB}_{\\text{HK1}} + 2 \\times \\text{ĐTB}_{\\text{HK2}}}{3} = \\frac{7{,}6 + 2y}{3}$$\nĐể đạt danh hiệu học sinh Giỏi cả năm, ta có bất phương trình:\n$$\\frac{7{,}6 + 2y}{3} \\ge 8{,}0$$\n$$7{,}6 + 2y \\ge 24{,}0$$\n$$2y \\ge 24{,}0 - 7{,}6 = 16{,}4$$\n$$y \\ge \\frac{16{,}4}{2} = 8{,}2$$\nVậy ở học kỳ 2, bạn Mai cần đạt điểm trung bình tối thiểu là $8{,}2$ điểm."
