          levelClass: "bg-blue-100 text-blue-800 font-bold",
          question: "Một cơ sở sản xuất đồ thủ công mỹ nghệ đầu tư mua khuôn đúc ban đầu hết $30\\,000\\,000\\text{ đồng}$. Chi phí nguyên vật liệu và công gia công cho mỗi sản phẩm là $80\\,000\\text{ đồng}$. Cơ sở dự kiến bán ra thị trường với giá $140\\,000\\text{ đồng/sản phẩm}$. Hỏi cơ sở phải sản xuất và bán ra tối thiểu bao nhiêu sản phẩm để bắt đầu thu được khoản lợi nhuận trên $18\\,000\\,000\\text{ đồng}$?",
          shortAnswer: "Tối thiểu $801$ sản phẩm.",
          fullSolution: "- Gọi số sản phẩm sản xuất và bán ra là $x$ ($x \\in \\mathbb{N}^*$).\n- Tổng doanh thu bán hàng: $140\\,000x$ (đồng).\n- Tổng chi phí sản xuất: $30\\,000\\,000 + 80\\,000x$ (đồng).\n- Lợi nhuận thu được là hiệu của doanh thu và chi phí:\n$$L(x) = 140\\,000x - (30\\,000\\,000 + 80\\,000x) = 60\\,000x - 30\\,000\\,000$$\nĐể lợi nhuận trên $18\\,000\\,000$ đồng, ta có bất phương trình:\n$$60\\,000x - 30\\,000\\,000 > 18\\,000\\,000$$\n$$60\\,000x > 48\\,000\\,000$$\n$$x > \\frac{48\\,000\\,000}{60\\,000} = 800$$\nVì $x$ là số nguyên dương nên $x \\ge 801$.\nVậy cơ sở phải sản xuất và tiêu thụ tối thiểu $801$ sản phẩm."
