          shortAnswer: "$\\frac{2}{5}$",
          fullSolution: "Khai phương từng thành phần:\n- $\\sqrt{\\frac{144}{25}} = \\frac{12}{5}$.\n- $\\sqrt{2\\frac{1}{4}} = \\sqrt{\\frac{9}{4}} = \\frac{3}{2}$.\n- $\\sqrt{\\frac{9}{16}} = \\frac{3}{4}$.\nThay vào biểu thức:\n$$G = \\frac{12}{5} - \\frac{3}{2} : \\frac{3}{4} = \\frac{12}{5} - \\left(\\frac{3}{2} \\times \\frac{4}{3}\\right) = \\frac{12}{5} - 2 = \\frac{12}{5} - \\frac{10}{5} = \\frac{2}{5}$$"
