          fullSolution: "Khai phương một tích: $\\sqrt{4x} = \\sqrt{4} \\times \\sqrt{x} = 2\\sqrt{x}$.\nTa có:\n$$2\\sqrt{x} = 8 \\iff \\sqrt{x} = 4 \\iff x = 4^2 = 16$$\nVậy $x = 16$."
