          question: "Giải phương trình: $\\sqrt{2}x - \\sqrt{50} = 0$.",
          shortAnswer: "$x = 5$",
          fullSolution: "Chuyển vế:\n$$\\sqrt{2}x = \\sqrt{50} \\iff x = \\frac{\\sqrt{50}}{\\sqrt{2}} = \\sqrt{\\frac{50}{2}} = \\sqrt{25} = 5$$\nVậy phương trình có nghiệm duy nhất $x = 5$."
