          levelClass: "bg-emerald-100 text-emerald-800",
          question: "Rút gọn biểu thức đồng dạng chứa căn thức: $A = 3\\sqrt{8} - 2\\sqrt{18} + \\sqrt{50}$.",
          shortAnswer: "$5\\sqrt{2}$",
          fullSolution: "Đưa thừa số ra ngoài dấu căn của từng số hạng:\n- $3\\sqrt{8} = 3\\sqrt{4 \\times 2} = 3 \\times 2\\sqrt{2} = 6\\sqrt{2}$.\n- $2\\sqrt{18} = 2\\sqrt{9 \\times 2} = 2 \\times 3\\sqrt{2} = 6\\sqrt{2}$.\n- $\\sqrt{50} = \\sqrt{25 \\times 2} = 5\\sqrt{2}$.\nThay vào biểu thức:\n$$A = 6\\sqrt{2} - 6\\sqrt{2} + 5\\sqrt{2} = 5\\sqrt{2}$$"
