          shortAnswer: "$x = \\frac{4}{3}$",
          fullSolution: "Ta có: $\\sqrt{(x - 3)^2} = 2x - 1 \\iff |x - 3| = 2x - 1$.\nĐiều kiện để phương trình có nghiệm: $2x - 1 \\ge 0 \\iff x \\ge \\frac{1}{2}$.\nXét hai trường hợp:\n1. Trường hợp 1: $x - 3 = 2x - 1 \\iff x = -2$ (loại vì không thỏa mãn $x \\ge \\frac{1}{2}$).\n2. Trường hợp 2: $x - 3 = -(2x - 1) = -2x + 1 \\iff 3x = 4 \\iff x = \\frac{4}{3}$ (thỏa mãn $x = \\frac{4}{3} \\ge \\frac{1}{2}$).\nVậy phương trình có nghiệm duy nhất $x = \\frac{4}{3}$."
