          question: "Tìm giá trị nhỏ nhất của biểu thức: $Q = \\frac{x + 3}{\\sqrt{x} + 1}$ với điều kiện $x \\ge 0$.",
          shortAnswer: "$Q_{\\min} = 2$ khi $x = 1$.",
          fullSolution: "Đặt $t = \\sqrt{x} \\ge 0 \\implies x = t^2$.\nBiến đổi biểu thức:\n$$Q = \\frac{t^2 + 3}{t + 1} = \\frac{(t^2 - 1) + 4}{t + 1} = (t - 1) + \\frac{4}{t + 1} = (t + 1) + \\frac{4}{t + 1} - 2$$\nVì $t \\ge 0 \\implies t + 1 > 0$. Áp dụng bất đẳng thức Cô-si cho hai số dương $(t + 1)$ và $\\frac{4}{t + 1}$:\n$$(t + 1) + \\frac{4}{t + 1} \\ge 2\\sqrt{(t + 1) \\times \\frac{4}{t + 1}} = 2 \\times 2 = 4$$\nDo đó: $Q \\ge 4 - 2 = 2$.\nDấu \"=\" xảy ra khi $t + 1 = \\frac{4}{t + 1} \\iff (t + 1)^2 = 4 \\iff t + 1 = 2 \\iff t = 1$ (vì $t \\ge 0$).\nVới $t = 1 \\implies \\sqrt{x} = 1 \\iff x = 1$ (thỏa mãn).\nVậy giá trị nhỏ nhất của $Q$ là $2$ khi $x = 1$."
