      description: "1. Định lý góc phụ nhau: Nếu hai góc nhọn phụ nhau (tổng bằng $90^\\circ$) thì sin góc này bằng côsin góc kia, tang góc này bằng côtang góc kia:\n$$\\sin \\alpha = \\cos(90^\\circ - \\alpha);\\quad \\cos \\alpha = \\sin(90^\\circ - \\alpha)$$\n$$\\tan \\alpha = \\cot(90^\\circ - \\alpha);\\quad \\cot \\alpha = \\tan(90^\\circ - \\alpha)$$\n2. Các hệ thức cơ bản giữa các tỉ số lượng giác:\n$$\\tan \\alpha = \\frac{\\sin \\alpha}{\\cos \\alpha};\\quad \\cot \\alpha = \\frac{\\cos \\alpha}{\\sin \\alpha};\\quad \\tan \\alpha \\cdot \\cot \\alpha = 1$$\n$$\\sin^2 \\alpha + \\cos^2 \\alpha = 1;\\quad 1 + \\tan^2 \\alpha = \\frac{1}{\\cos^2 \\alpha};\\quad 1 + \\cot^2 \\alpha = \\frac{1}{\\sin^2 \\alpha}$$",
