          question: "Cho góc nhọn $\\alpha$ thỏa mãn $\\sin \\alpha + \\cos \\alpha = \\frac{7}{5}$. Tính giá trị của tích $\\sin \\alpha \\cos \\alpha$ và biểu thức $P = \\sin^4 \\alpha + \\cos^4 \\alpha$.",
          shortAnswer: "$\\sin \\alpha \\cos \\alpha = \\frac{12}{25}$ và $P = \\frac{337}{625}$.",
          fullSolution: "1. Bình phương hai vế của đẳng thức đã cho:\n$$(\\sin \\alpha + \\cos \\alpha)^2 = \\left(\\frac{7}{5}\\right)^2$$\n$$\\sin^2 \\alpha + 2\\sin \\alpha \\cos \\alpha + \\cos^2 \\alpha = \\frac{49}{25}$$\n$$1 + 2\\sin \\alpha \\cos \\alpha = \\frac{49}{25} \\implies 2\\sin \\alpha \\cos \\alpha = \\frac{49}{25} - 1 = \\frac{24}{25} \\implies \\sin \\alpha \\cos \\alpha = \\frac{12}{25}$$\n2. Biến đổi biểu thức $P$:\n$$P = \\sin^4 \\alpha + \\cos^4 \\alpha = (\\sin^2 \\alpha + \\cos^2 \\alpha)^2 - 2\\sin^2 \\alpha \\cos^2 \\alpha$$\n$$P = 1^2 - 2(\\sin \\alpha \\cos \\alpha)^2 = 1 - 2 \\times \\left(\\frac{12}{25}\\right)^2 = 1 - 2 \\times \\frac{144}{625} = 1 - \\frac{288}{625} = \\frac{337}{625}$$"
