          question: "Cho đường tròn $(O; 6\\text{ cm})$ và một đường thẳng $a$. Xác định vị trí tương đối của $a$ và $(O)$ trong các trường hợp sau:\na) $d = 4\\text{ cm}$;\nb) $d = 6\\text{ cm}$;\nc) $d = 8\\text{ cm}$.",
