          levelClass: "bg-slate-100 text-slate-700",
          question: "Đường thẳng $\\Delta$ cắt đường tròn $(O; 10\\text{ cm})$ tạo thành một dây cung có độ dài bằng $16\\text{ cm}$. Tính khoảng cách $d$ từ tâm $O$ đến đường thẳng $\\Delta$.",
          shortAnswer: "$d = 6\\text{ cm}$",
          fullSolution: "Kẻ $OH \\perp \\Delta$ tại $H \\implies OH = d$ và $H$ là trung điểm của dây cung $AB = 16\\text{ cm}$.\nTa có $AH = \\frac{AB}{2} = 8\\text{ cm}$. Trong tam giác vuông $OAH$:\n$$d = OH = \\sqrt{OA^2 - AH^2} = \\sqrt{10^2 - 8^2} = \\sqrt{36} = 6\\text{ (cm)}$$"
