          shortAnswer: "Đường thẳng $y = 3$ cắt đường tròn tại hai điểm chung.",
          fullSolution: "Khoảng cách từ gốc tọa độ $O(0; 0)$ đến đường thẳng nằm ngang $y = 3$ là $d = |3 - 0| = 3$.\nSo sánh khoảng cách $d$ với bán kính $R = 5$:\n$$d = 3 < 5 = R$$\nVì $d < R$ nên đường thẳng $y = 3$ cắt đường tròn tại hai điểm phân biệt có tọa độ là $(-4; 3)$ và $(4; 3)$."
