          question: "Cho đường tròn $(O; 5\\text{ cm})$ và điểm $A$ cách tâm $O$ một khoảng bằng $10\\text{ cm}$. Kẻ tiếp tuyến $AB$ với đường tròn ($B$ là tiếp điểm). Tính độ dài đoạn thẳng tiếp tuyến $AB$.",
          shortAnswer: "$AB = 5\\sqrt{3}\\text{ cm}$",
          fullSolution: "Vì $AB$ là tiếp tuyến của $(O)$ tại $B$ nên $OB \\perp AB$ tại $B$ ($OB = R = 5\\text{ cm}$).\nXét tam giác $OAB$ vuông tại $B$, theo định lý Pythagore:\n$$AB = \\sqrt{OA^2 - OB^2} = \\sqrt{10^2 - 5^2} = \\sqrt{100 - 25} = \\sqrt{75} = 5\\sqrt{3}\\text{ (cm)}$$"
