          question: "Cho đường tròn $(O; R)$ và đường thẳng $\\Delta$ không giao nhau với đường tròn ($d > R$). Điểm $M$ di chuyển trên đường thẳng $\\Delta$. Tìm vị trí của điểm $M$ trên $\\Delta$ sao cho độ dài đoạn thẳng $OM$ ngắn nhất.",
          shortAnswer: "$M$ là hình chiếu vuông góc của tâm $O$ trên đường thẳng $\\Delta$.",
          fullSolution: "Kẻ $OH \\perp \\Delta$ tại $H$. Khi đó $H$ là điểm cố định trên đường thẳng $\\Delta$ và khoảng cách $OH = d$.\nVới điểm $M$ bất kỳ trên $\\Delta$, tam giác $OHM$ vuông tại $H$, do đó cạnh huyền $OM$ luôn lớn hơn hoặc bằng cạnh góc vuông $OH$:\n$$OM \\ge OH = d$$\nDấu đẳng thức xảy ra khi và chỉ khi $M \\equiv H$.\nVậy vị trí của $M$ trên $\\Delta$ để khoảng cách $OM$ ngắn nhất chính là hình chiếu vuông góc của tâm $O$ lên đường thẳng $\\Delta$."
