          fullSolution: "1. Phương trình đường thẳng $AB$ đi qua hai điểm $A(-1; 1)$ và $B(2; 4)$ có hệ số góc $k = \\frac{4 - 1}{2 - (-1)} = 1$.\nPhương trình đường thẳng $AB$ là: $y = x + 2$.\n2. Đường thẳng $AB$ cắt trục tung $Oy$ tại điểm $C(0; 2)$.\nĐoạn thẳng $OC$ nằm trên trục tung có độ dài: $OC = 2$.\n3. Diện tích tam giác $OAB$ được tách thành tổng diện tích hai tam giác $\\triangle OAC$ và $\\triangle OBC$ chung đáy $OC$:\n$$S_{\\triangle OAB} = S_{\\triangle OAC} + S_{\\triangle OBC} = \\frac{1}{2} OC \\times |x_A| + \\frac{1}{2} OC \\times |x_B|$$\n$$S_{\\triangle OAB} = \\frac{1}{2} \\times 2 \\times |-1| + \\frac{1}{2} \\times 2 \\times |2| = 1 + 2 = 3\\text{ (đvdt)}$$"
