          question: "Cho Parabol $(P): y = \\frac{1}{4}x^2$. Tìm tọa độ điểm $M$ thuộc $(P)$ sao cho khoảng cách từ $M$ đến trục hoành $Ox$ gấp đôi khoảng cách từ $M$ đến trục tung $Oy$ và $x_M > 0$.",
