          fullSolution: "1. Khoảng cách từ điểm $M(x; y)$ đến trục hoành là $|y|$ và đến trục tung là $|x|$.\nVì điểm $M$ thuộc $(P)$ nên $y = \\frac{1}{4}x^2 \\ge 0$, và theo giả thiết $x > 0$, ta có $|y| = y$ và $|x| = x$.\n2. Theo bài ra: khoảng cách đến $Ox$ gấp đôi khoảng cách đến $Oy$:\n$$y = 2x$$\nThay vào phương trình Parabol:\n$$\\frac{1}{4}x^2 = 2x \\iff x^2 - 8x = 0 \\iff x(x - 8) = 0$$\nVì $x > 0$ nên $x = 8$.\nTung độ tương ứng: $y = 2 \\times 8 = 16$.\nVậy tọa độ điểm $M$ là $(8; 16)$."
