      description: "Biểu thức đối xứng giữa hai nghiệm là biểu thức không thay đổi giá trị khi ta hoán đổi vị trí của $x_1$ và $x_2$. Các hằng đẳng thức thường dùng biến đổi về tổng $S = x_1 + x_2$ và tích $P = x_1 x_2$:\n- $x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1 x_2 = S^2 - 2P$.\n- $(x_1 - x_2)^2 = (x_1 + x_2)^2 - 4x_1 x_2 = S^2 - 4P$.\n- $x_1^3 + x_2^3 = (x_1 + x_2)^3 - 3x_1 x_2(x_1 + x_2) = S^3 - 3SP$.\n- $\\frac{1}{x_1} + \\frac{1}{x_2} = \\frac{x_1 + x_2}{x_1 x_2} = \\frac{S}{P}$.",
