          shortAnswer: "$x_1^2 + x_2^2 = S^2 - 2P$ và $\\frac{1}{x_1} + \\frac{1}{x_2} = \\frac{S}{P}$.",
          fullSolution: "- $x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1 x_2 = S^2 - 2P$.\n- $\\frac{1}{x_1} + \\frac{1}{x_2} = \\frac{x_1 + x_2}{x_1 x_2} = \\frac{S}{P}$ ($P \\ne 0$)."
