          question: "Cho phương trình $x^2 - 5x + 3 = 0$ có hai nghiệm $x_1, x_2$. Tính giá trị của biểu thức: $A = x_1^2 + x_2^2$.",
          shortAnswer: "$A = 19$",
          fullSolution: "Theo định lí Vi-ét: $S = x_1 + x_2 = 5$ và $P = x_1 x_2 = 3$.\nGiá trị của biểu thức là:\n$$A = x_1^2 + x_2^2 = S^2 - 2P = 5^2 - 2 \\times 3 = 25 - 6 = 19$$"
