          shortAnswer: "$D = 2\\sqrt{2}$",
          fullSolution: "Theo định lí Vi-ét: $S = x_1 + x_2 = 6$ và $P = x_1 x_2 = 7$.\nTa tính bình phương của độ lệch:\n$$D^2 = (x_1 - x_2)^2 = (x_1 + x_2)^2 - 4x_1 x_2 = S^2 - 4P = 6^2 - 4 \\times 7 = 36 - 28 = 8$$\nSuy ra:\n$$D = |x_1 - x_2| = \\sqrt{8} = 2\\sqrt{2}$$"
