          fullSolution: "Quy trình 4 bước chuẩn mực:\n1. Bước 1: Tìm điều kiện của $m$ để phương trình có nghiệm ($a \\ne 0$ và $\\Delta \\ge 0$ hoặc $\\Delta > 0$).\n2. Bước 2: Viết hệ thức Vi-ét biểu thị $x_1 + x_2 = -\\frac{b}{a}$ và $x_1 x_2 = \\frac{c}{a}$ theo $m$.\n3. Bước 3: Biến đổi điều kiện bài toán về biểu thức chứa tổng và tích của hai nghiệm.\n4. Bước 4: Thay hệ thức Vi-ét vào, giải tìm $m$, đối chiếu với điều kiện ở Bước 1 và kết luận."
