          shortAnswer: "$50\\text{ km/h}$",
          fullSolution: "1. Đổi $24\\text{ phút} = \\frac{24}{60}\\text{ h} = \\frac{2}{5}\\text{ h}$.\n2. Gọi vận tốc lúc đi của ô tô là $x$ ($x > 0$, km/h).\nVận tốc lúc về là: $x + 10$ (km/h).\n- Thời gian lúc đi: $\\frac{120}{x}$ (h).\n- Thời gian lúc về: $\\frac{120}{x + 10}$ (h).\n3. Vì thời gian về ít hơn thời gian đi $\\frac{2}{5}$ giờ, ta có phương trình:\n$$\\frac{120}{x} - \\frac{120}{x + 10} = \\frac{2}{5}$$\nChia cả hai vế cho $2$:\n$$\\frac{60}{x} - \\frac{60}{x + 10} = \\frac{1}{5}$$\nQuy đồng mẫu số chung $5x(x + 10)$ và khử mẫu:\n$$300(x + 10) - 300x = x(x + 10)$$\n$$3000 = x^2 + 10x \\iff x^2 + 10x - 3000 = 0$$\n4. Giải phương trình: $\\Delta' = 5^2 - 1(-3000) = 25 + 3000 = 3025 = 55^2$.\nNghiệm dương: $x = -5 + 55 = 50\\text{ (km/h)}$ (loại nghiệm $x = -60$).\nVậy vận tốc của ô tô lúc đi là $50\\text{ km/h}$."
