          shortAnswer: "$12\\text{ km/h}$",
          fullSolution: "1. Đổi $30\\text{ phút} = 0{,}5\\text{ h} = \\frac{1}{2}\\text{ h}$.\n2. Gọi vận tốc lúc đi là $x$ ($x > 0$, km/h). Vận tốc lúc về là $x + 4$ (km/h).\nTa có phương trình biểu thị sự chênh lệch thời gian:\n$$\\frac{24}{x} - \\frac{24}{x + 4} = \\frac{1}{2}$$\n$$24 \\times 2(x + 4) - 48x = x(x + 4)$$\n$$48x + 192 - 48x = x^2 + 4x \\iff x^2 + 4x - 192 = 0$$\n3. Giải phương trình: $\\Delta' = 2^2 - 1(-192) = 4 + 192 = 196 = 14^2$.\nNghiệm dương: $x = -2 + 14 = 12\\text{ (km/h)}$ (loại $x = -16$).\nVậy vận tốc của xe đạp lúc đi là $12\\text{ km/h}$."
