          shortAnswer: "$AB = CD$ do tính đối xứng qua đường kính vuông góc với cát tuyến",
          fullSolution: "Kẻ $OH \\perp AD$ tại $H$. Khi đó $OH$ cũng vuông góc với $BC$ tại $H$.\n- Trong đường tròn nhỏ $(O; r)$: đường kính vuông góc với dây $BC$ nên $H$ là trung điểm của $BC$, tức $HB = HC$.\n- Trong đường tròn lớn $(O; R)$: đường kính vuông góc với dây $AD$ nên $H$ là trung điểm của $AD$, tức $HA = HD$.\nTrừ vế theo vế hai đẳng thức:\n$$HA - HB = HD - HC \\implies AB = CD$$\nĐẳng thức được chứng minh."
