          question: "Cho tứ giác $ABCD$ nội tiếp đường tròn $(O)$. Hai tia $AB$ và $DC$ cắt nhau tại điểm $E$. Biết $\\widehat{BCE} = 75^\\circ$ và $\\widehat{E} = 40^\\circ$. Tính các góc của tứ giác $ABCD$.",
          shortAnswer: "$\\widehat{A} = 75^\\circ; \\widehat{B} = 65^\\circ; \\widehat{C} = 105^\\circ; \\widehat{D} = 115^\\circ$",
          fullSolution: "1. Trong tam giác $EBC$, góc $\\widehat{BCE} = 75^\\circ, \\widehat{E} = 40^\\circ$.\nSuy ra góc ngoài hoặc góc trong $\\widehat{EBC} = 180^\\circ - (75^\\circ + 40^\\circ) = 65^\\circ$.\n2. Trong tứ giác nội tiếp $ABCD$:\n- Góc ngoài tại đỉnh $C$ đối diện góc $A$, do $E, C, D$ thẳng hàng nên $\\widehat{BCE}$ chính là góc ngoài tại $C$ của tứ giác. Do đó $\\widehat{A} = \\widehat{BCE} = 75^\\circ$.\n- $\\widehat{C} = 180^\\circ - \\widehat{BCE} = 105^\\circ$.\n- Góc $\\widehat{EBC}$ là góc kề bù với góc $\\widehat{ABC}$, do đó $\\widehat{ABC} = 180^\\circ - 65^\\circ = 115^\\circ$ (hoặc $\\widehat{B} = 65^\\circ$ tùy thứ tự đỉnh kề).\nCụ thể $\\widehat{D} = 180^\\circ - \\widehat{B} = 180^\\circ - 115^\\circ = 65^\\circ$."
