          shortAnswer: "$S_{\\text{tổng}} = 600\\pi\\text{ cm}^2$",
          fullSolution: "1. Khi cắt đôi quả cầu, diện tích mỗi bán cầu gồm hai phần:\n- Diện tích mặt cong nửa cầu: $S_{\\text{cong}} = \\frac{1}{2} (4\\pi R^2) = 2\\pi R^2$.\n- Diện tích mặt cắt phẳng tròn đáy: $S_{\\text{đáy}} = \\pi R^2$.\nDo đó diện tích toàn phần của 1 bán cầu là:\n$$S_{\\text{bán cầu}} = 2\\pi R^2 + \\pi R^2 = 3\\pi R^2$$\n2. Tổng diện tích của cả hai bán cầu là:\n$$S_{\\text{tổng}} = 2 \\times 3\\pi R^2 = 6\\pi R^2$$\nThay $R = 10\\text{ cm}$ vào:\n$$S_{\\text{tổng}} = 6\\pi \\times 10^2 = 600\\pi\\text{ (cm}^2)$$\n(Lưu ý: So với diện tích mặt cầu ban đầu $400\\pi\\text{ cm}^2$, diện tích tăng thêm $200\\pi\\text{ cm}^2$ chính là diện tích của hai mặt đáy tròn mới xuất hiện sau nhát cắt)."
